public sealed class CoreAudioVolumeService:ISystemVolumeService,IDisposable
{
    private IAudioEndpointVolume? _endpoint;private string? _endpointId;private EndpointCallback? _callback;
    public event EventHandler<SystemVolumeChangedEventArgs>? VolumeChanged;
    public Task<SystemVolumeState> GetStateAsync(CancellationToken cancellationToken=default)=>Task.FromResult(ReadState());
    public Task SetVolumeAsync(double normalizedVolume,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();IAudioEndpointVolume endpoint=GetEndpoint();Marshal.ThrowExceptionForHR(endpoint.SetMasterVolumeLevelScalar((float)Math.Clamp(normalizedVolume,0,1),Guid.Empty));Raise();return Task.CompletedTask;}
    public Task SetMutedAsync(bool muted,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();IAudioEndpointVolume endpoint=GetEndpoint();Marshal.ThrowExceptionForHR(endpoint.SetMute(muted,Guid.Empty));Raise();return Task.CompletedTask;}
    public void Dispose(){if(_endpoint is not null&&_callback is not null){try{_endpoint.UnregisterControlChangeNotify(_callback);}catch(COMException){}}_endpoint=null;_callback=null;}
    private SystemVolumeState ReadState(){try{IAudioEndpointVolume endpoint=GetEndpoint();Marshal.ThrowExceptionForHR(endpoint.GetMasterVolumeLevelScalar(out float volume));Marshal.ThrowExceptionForHR(endpoint.GetMute(out bool muted));return new(volume,muted,_endpointId,"Default audio output",true);}catch(Exception ex) when(ex is COMException or InvalidOperationException){return new(0,false,null,null,false,ex.Message);}}
    private IAudioEndpointVolume GetEndpoint(){if(_endpoint is not null)return _endpoint;IMMDeviceEnumerator enumerator=(IMMDeviceEnumerator)(object)new MMDeviceEnumerator();Marshal.ThrowExceptionForHR(enumerator.GetDefaultAudioEndpoint(EDataFlow.Render,ERole.Multimedia,out IMMDevice device));Marshal.ThrowExceptionForHR(device.GetId(out _endpointId!));Guid iid=typeof(IAudioEndpointVolume).GUID;Marshal.ThrowExceptionForHR(device.Activate(ref iid,23,IntPtr.Zero,out object endpoint));_endpoint=(IAudioEndpointVolume)endpoint;_callback=new EndpointCallback(this);Marshal.ThrowExceptionForHR(_endpoint.RegisterControlChangeNotify(_callback));return _endpoint;}
    private void Raise()=>VolumeChanged?.Invoke(this,new(ReadState()));
    [ComVisible(true),ClassInterface(ClassInterfaceType.None)]private sealed class EndpointCallback(CoreAudioVolumeService owner):IAudioEndpointVolumeCallback{public int OnNotify(IntPtr data){owner.Raise();return 0;}}
}

public sealed class CoreAudioOutputDeviceService:IAudioOutputDeviceService,IDisposable
{
    private IMMDeviceEnumerator? _enumerator;private DeviceNotificationCallback? _callback;
    public CoreAudioOutputDeviceService(){try{_enumerator=(IMMDeviceEnumerator)(object)new MMDeviceEnumerator();_callback=new(this);Marshal.ThrowExceptionForHR(_enumerator.RegisterEndpointNotificationCallback(_callback));}catch(COMException){_enumerator=null;_callback=null;}}
    public event EventHandler<AudioOutputDevicesChangedEventArgs>? DevicesChanged;
    public Task<AudioOutputSnapshot> GetSnapshotAsync(CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();try{IMMDeviceEnumerator enumerator=_enumerator??(IMMDeviceEnumerator)(object)new MMDeviceEnumerator();Marshal.ThrowExceptionForHR(enumerator.GetDefaultAudioEndpoint(EDataFlow.Render,ERole.Multimedia,out IMMDevice defaultDevice));Marshal.ThrowExceptionForHR(defaultDevice.GetId(out string defaultId));Marshal.ThrowExceptionForHR(enumerator.EnumAudioEndpoints(EDataFlow.Render,1,out IMMDeviceCollection collection));Marshal.ThrowExceptionForHR(collection.GetCount(out uint count));List<AudioOutputDevice> devices=[];for(uint i=0;i<count;i++){Marshal.ThrowExceptionForHR(collection.Item(i,out IMMDevice device));Marshal.ThrowExceptionForHR(device.GetId(out string id));devices.Add(new(id,id,"Active",id==defaultId,null));}AudioOutputSnapshot snapshot=new(devices,defaultId,false);return Task.FromResult(snapshot);}catch(Exception ex) when(ex is COMException or InvalidOperationException){return Task.FromResult(new AudioOutputSnapshot([],null,false,ex.Message));}}
    public Task<AudioOutputChangeResult> SetDefaultOutputAsync(string deviceId,CancellationToken cancellationToken=default){cancellationToken.ThrowIfCancellationRequested();if(string.IsNullOrWhiteSpace(deviceId))return Task.FromResult(new AudioOutputChangeResult(false,false,"A device must be selected."));try{Process.Start(new ProcessStartInfo("ms-settings:sound"){UseShellExecute=true});return Task.FromResult(new AudioOutputChangeResult(false,true,"Windows does not expose a supported public API for changing the default endpoint; Sound Settings was opened."));}catch(Exception ex) when(ex is InvalidOperationException or System.ComponentModel.Win32Exception){return Task.FromResult(new AudioOutputChangeResult(false,false,ex.Message));}}
    internal void NotifyForTest(AudioOutputSnapshot snapshot)=>DevicesChanged?.Invoke(this,new(snapshot));
    public void Dispose(){if(_enumerator is not null&&_callback is not null){try{_enumerator.UnregisterEndpointNotificationCallback(_callback);}catch(COMException){}}_callback=null;_enumerator=null;}
    private async void Notify(){DevicesChanged?.Invoke(this,new(await GetSnapshotAsync()));}
    [ComVisible(true),ClassInterface(ClassInterfaceType.None)]private sealed class DeviceNotificationCallback(CoreAudioOutputDeviceService owner):IMMNotificationClient{public int OnDeviceStateChanged(string id,uint state){owner.Notify();return 0;}public int OnDeviceAdded(string id){owner.Notify();return 0;}public int OnDeviceRemoved(string id){owner.Notify();return 0;}public int OnDefaultDeviceChanged(EDataFlow flow,ERole role,string? id){if(flow is EDataFlow.Render or EDataFlow.All)owner.Notify();return 0;}public int OnPropertyValueChanged(string id,PropertyKey key){owner.Notify();return 0;}}
}

